from kit_trainer import *
A='client'
kv=lambda k,v,vc='':f'<div class="row sp" style="padding:9px 0;border-top:.5px solid var(--line)"><span class="t-sub">{k}</span><span class="t-bodym tnum" style="font-size:15px;{vc}">{v}</span></div>'
card=lambda t,inner,right='',st='':f'<div class="card" style="padding:14px 16px;margin-top:12px;{st}"><div class="row sp"><span class="t-head">{t}</span>{right}</div>{inner}</div>'
link=lambda t:f'<span class="link" style="font-size:14.5px">{t}</span>'
ACTS=lambda dis=False:f'<div class="row" style="gap:8px;margin-top:14px">{btn("WhatsApp","dis" if dis else "tint",icon="message-circle",cls="sm",style="flex:1")}{btn("Nudge…","dis" if dis else "secondary",cls="sm",style="flex:1")}{btn("Note","dis" if dis else "secondary",icon="notebook-pen",cls="sm",style="flex:1")}</div>'
def overview(n,chips,sub,week,wk_counts,kcal,attn,nextci,extra_top='',tz='',acts=None):
    return page(nav("",left="back",right='<div class="circbtn sm">'+ic("ellipsis",18,2.2)+'</div>'),f'''{extra_top}{chdr(n,chips,sub,tz)}{acts if acts is not None else ACTS()}
{attn}{card("This week",wdots(week)+f'<div class="row" style="gap:16px;margin-top:12px">{wk_counts}</div>',f'<span class="t-cap">Mon 9 – Sun 15 Nov</span>')}
{card("Today’s food",f'<div class="row" style="gap:12px;margin-top:8px;align-items:baseline"><span class="n-lg">{kcal[0]}</span><span class="t-sub">of {kcal[1]} kcal planned</span><span style="margin-left:auto">{link("Review day")}</span></div><div class="track" style="height:6px;margin-top:8px"><i style="width:{min(100,kcal[2])}%;background:{"var(--warn)" if kcal[2]>100 else "var(--brand)"}"></i></div>')}
{card("Next check-in",f'<div class="t-sub" style="margin-top:4px">{nextci}</div>')}''')
ATTN_R=card("Needs attention",f'<div class="row" style="gap:10px;margin-top:8px">{sch("crit")}<span class="t-body" style="font-size:15px">Missed 2 workouts · Tue, Thu</span></div><div style="margin-top:10px">{btn("Review","tint",cls="sm")}</div>',f'<span class="t-cap">since 5 d</span>')
screen('TM-03a-client-overview','Client overview: Rohan (needs attention)',overview("Rohan",sch("crit","Needs attention"),"Fat loss · week 6 of 12",["rest","miss","rest","miss","rest","today","plan"],'<span class="t-sub"><b class="b">0 of 3</b> workouts</span><span class="t-sub"><b class="b">14 of 25</b> meals</span>',(640,1900,34),ATTN_R,"Weekly · due Sun 15 Nov · not started"),A)
act=lambda i,t,w:f'<div class="row" style="gap:10px;padding:9px 0;border-top:.5px solid var(--line)">{ic(i,17,2,"var(--ink3)")}<span class="t-body f1" style="font-size:15px">{t}</span><span class="t-cap">{w}</span></div>'
screen('TM-03b-client-overview-scrolled','Client overview scrolled: activity, reminders, notes, profile',f'''<div class="content" style="top:44px">
{card("Recent activity",act("utensils","Logged Lunch · as planned","1:40 pm")+act("utensils","Logged Breakfast · as planned","8:52 am")+act("eye","Saw your note","Fri")+act("calendar-x","Missed Upper body B","Thu")+act("dumbbell","Finished Lower body A","Sat 7"),link("See all"))}
{card("Reminders",f'<div class="t-sub" style="margin-top:4px">On · workout 6:00 pm, meals when due, check-in Sun 9 am. Quiet 10 pm – 7 am.</div><div class="t-cap" style="margin-top:6px">Last reminder delivered Thu 6:00 pm · not opened</div>')}
{card("Coach notes",f'<div style="margin-top:8px;padding:10px 12px;border-radius:12px;background:var(--bg)"><div class="row sp"><span class="t-cap">Shared on Rohan’s Today · Fri</span>{ic("eye",14,2,"var(--ink3)")}</div><div class="t-body" style="font-size:15px;margin-top:4px">Two shorter sessions this week while you travel.</div></div><div style="margin-top:8px;padding:10px 12px;border-radius:12px;background:var(--bg)"><div class="row sp"><span class="t-cap">Only you · 2 Nov</span>{ic("lock",14,2,"var(--ink3)")}</div><div class="t-body" style="font-size:15px;margin-top:4px">Responds better to a call than texts.</div></div>',link("Add note"))}
{card("Profile and safety",f'<div class="row" style="gap:10px;margin-top:8px">{sch("warn","Limitation")}<span class="t-body" style="font-size:15px">Left knee, no deep lunges</span></div><div style="margin-top:10px">{link("Goal, intake answers, limitations")}</div>')}
<div class="card" style="padding:14px 16px;margin-top:12px"><div class="row sp"><div><div class="t-bodym">Edit plan</div><div class="t-sub" style="font-size:13.5px">Plans and templates are built on FitBud web</div></div>{btn("Copy link","secondary",icon="copy",cls="sm")}</div></div><div style="height:40px"></div></div>''',A)
TZ='<span class="tz">'+ic("globe",13,2.2)+'Deepak’s time 8:10 am · 1 h 30 m behind</span>'
ATTN_D=card("Needs attention",f'<div class="row" style="gap:10px;margin-top:8px">{sch("ci")}<span class="t-body" style="font-size:15px">Check-in · week 8 · 4 h ago</span></div><div style="margin-top:10px">{btn("Review check-in","tint",cls="sm")}</div>')
screen('TM-03c-client-other-timezone','Client in another time zone (Deepak, Dubai)',overview("Deepak",sch("ok"),"Muscle gain · week 8 of 12",["ok","rest","ok","ok","rest","ok","today"],'<span class="t-sub"><b class="b">4 of 4</b> workouts</span><span class="t-sub"><b class="b">27 of 30</b> meals</span>',(820,2600,32),ATTN_D,"Submitted today · waiting for your review",tz=TZ),A)
screen('TM-03d-client-ended','Ended client: read only, Reactivate',overview("Kavya",sch("end"),"Fat loss · ended 30 Oct",["plan"]*7,'<span class="t-sub">No plan since 30 Oct</span>',(0,0,0),'',"No check-ins after coaching ended",extra_top=f'<div style="margin-bottom:12px">{banner("Coaching ended on 30 Oct. History is read only.","neutral","circle-slash",link("Reactivate"))}</div>',acts=ACTS(True)).replace("of 0 kcal planned","kcal · no plan"),A)
screen('TM-03e-reactivate-sheet','Reactivate confirm sheet',overview("Kavya",sch("end"),"Fat loss · ended 30 Oct",["plan"]*7,'<span class="t-sub">No plan since 30 Oct</span>',(0,0,0),'',"—",acts=ACTS(True))+sheet(f'''<div class="t-title">Reactivate Kavya?</div><div class="t-sub" style="margin-top:4px">She gets a WhatsApp invite to rejoin. Her old plan isn’t restarted. Assign a new one on FitBud web.</div>
<div class="group" style="margin-top:14px;background:var(--bg);box-shadow:none">{li("History","Kept · 6 weeks of logs",chev=False)}{li("Plan","None until you assign one",chev=False)}</div><div style="margin-top:14px">{btn("Send invite to rejoin",icon="message-circle")}</div><div style="margin-top:8px">{btn("Cancel","secondary")}</div>'''),A)
screen('TM-03f-client-info','Client info: goal, intake, limitations',page(nav("Rohan · info"),f'''{group([li("Goal","Lose 6 kg by Feb · fat loss",chev=False),li("Started","3 Oct · week 6 of 12",chev=False),li("Height · start weight","175 cm · 86.4 kg",chev=False)],"Coaching")}
{group([f'<div class="li" style="--inset:14px;align-items:flex-start"><div class="f1"><div class="row" style="gap:6px">{sch("warn","Limitation")}</div><div class="t-body" style="margin-top:6px">Left knee: no deep lunges or jumps. Physio says OK for leg press.</div><div class="t-cap" style="margin-top:4px">From intake · edited by you 20 Oct</div></div></div>'],"Limitations and injuries")}
{group([li("Diet","Vegetarian · eats eggs",chev=False),li("Training","Gym, 3 days a week",chev=False),li("Intake answers","Submitted 2 Oct","file-text")],"Intake")}
{group([li("WhatsApp","+91 98110 22334",chev=False),li("Time zone","India (IST)",chev=False)],"Contact")}<div class="t-cap" style="margin:8px 2px">Edit goals and limitations on FitBud web.</div>'''),A)
screen('TM-03g-client-onboarding','Onboarding not finished (Vikram)',page(nav("",left="back"),f'''{chdr("Vikram",sch("onb","Intake not sent"),"Joined 11 Nov · no plan yet")}
<div class="card" style="padding:16px;margin-top:16px"><div class="t-head">Waiting for Vikram’s intake</div><div class="t-sub" style="margin-top:4px">He accepted your invite 3 days ago but hasn’t sent the intake form, so you can’t plan yet.</div>
<div style="margin-top:12px">{btn("Remind on WhatsApp",icon="message-circle")}</div></div>
{card("Steps",''.join(f'<div class="row" style="gap:10px;padding:9px 0;border-top:.5px solid var(--line)">{ic(i,18,2.2,c)}<span class="t-body f1" style="font-size:15px">{t}</span></div>' for i,t,c in [("circle-check","Accepted invite","var(--done)"),("circle","Intake form","var(--ink4)"),("circle","Plan assigned (on web)","var(--ink4)")]))}'''),A)
# Session view (TM-11)
def srow(n,kg,reps,plan='',tag_=''):
    return f'<div class="t-sub">{n}</div><div class="t-bodym" style="font-size:15px">{kg}</div><div class="t-bodym" style="font-size:15px">{reps} {tag_}</div><div class="t-cap" style="justify-content:flex-end">{plan}</div>'
def exblock(name,meta,rows,badge=''):
    return f'<div class="card" style="padding:12px 16px;margin-top:10px"><div class="row sp"><span class="t-bodym" style="color:var(--brand)">{name}</span>{badge}</div><div class="t-cap">{meta}</div><div class="stbl" data-wrapok="1" style="margin-top:6px"><div class="t-label" style="color:var(--ink3)">Set</div><div class="t-label" style="color:var(--ink3)">kg</div><div class="t-label" style="color:var(--ink3)">Reps</div><div></div>{rows}</div></div>'
pr=sch('pr','PR')
SESS=f'''{chdr("Aarav",sch("ok","Finished")+sch("pr","1 new best"),"Lower body B · today 6:31–7:23 pm")}
{hstat([("52 min","Duration"),("4,120 kg","Volume"),("17 / 18","Sets"),("7 / 10","Effort")])}
<div class="card" style="padding:12px 14px;margin-top:14px;background:var(--brand-tint);box-shadow:none"><div class="t-cap" style="color:var(--brand-ink)">Note from Aarav</div><div class="t-body" style="font-size:15px;margin-top:2px">Lower back tight on the last RDL set. Added hip thrusts instead of the last lunge set.</div></div>
<div class="t-label glabel">Changes from your plan</div><div class="row" style="gap:6px;flex-wrap:wrap">{sch("rev","+1 set Goblet squat")}{sch("rev","+ Hip thrust")}{sch("rev","−1 set Calf raise")}</div>
{exblock("Goblet squat","Plan 3 × 12 · 16 kg",srow(1,16,12)+srow(2,16,12)+srow(3,16,12)+srow(4,16,10,'','<span class="sch" style="background:var(--brand-tint);color:var(--brand-ink);height:18px;font-size:11px">Added</span>'))}
{exblock("Romanian deadlift","Plan 3 × 8–10 · 40 kg",srow(1,40,10)+srow(2,42.5,10,'',pr)+srow(3,42.5,9),sch("pain","Asked you"))}
{exblock("Hip thrust","Not in your plan · added by Aarav",srow(1,40,12)+srow(2,40,12),'<span class="sch" style="background:var(--brand-tint);color:var(--brand-ink)">Added by Aarav</span>')}'''
screen('TM-11a-session-detail','Trainee workout: sets vs plan, PR, trainee-added work',page(nav("Workout",right='<div class="circbtn sm">'+ic("ellipsis",18,2.2)+'</div>'),SESS)+stick2(btn("Add note","secondary",icon="notebook-pen"),btn("Reply on WhatsApp",icon="message-circle")),A)
screen('TM-11b-session-finished-early','Finished early, sets skipped (Rohan)',page(nav("Workout"),f'''{chdr("Rohan",sch("warn","Finished early"),"Lower body A · Sat 7 Nov · 31 min")}
{hstat([("31 min","Duration"),("1,880 kg","Volume"),("9 / 16","Sets"),("—","Effort")])}
<div style="margin-top:14px">{banner("7 sets weren’t logged. Rohan finished early and skipped Walking lunge and Calf raise.","warn","triangle-alert")}</div>
{exblock("Back squat","Plan 4 × 6 · 60 kg",srow(1,60,6)+srow(2,60,6)+srow(3,60,5)+'<div class="t-sub">4</div><div class="t-sub">—</div><div class="t-sub">Skipped</div><div></div>')}
{exblock("Walking lunge","Plan 3 × 12 / leg",'<div class="t-sub">—</div><div class="t-sub" style="grid-column:span 3">Skipped all 3 sets</div>',sch("rev","Skipped"))}''')+stick2(btn("Add note","secondary",icon="notebook-pen"),btn("Reply on WhatsApp",icon="message-circle")),A)
# Diet day review (TM-12)
def mrow(name,time,sub,kcal,plan,chip):
    return f'<div class="crow" style="align-items:flex-start"><div class="f1" style="min-width:0"><div class="row sp"><span class="t-bodym">{name} <span class="t-cap">{time}</span></span><span class="n-sm">{kcal}<span class="t-cap"> / {plan}</span></span></div><div class="t-sub" style="font-size:13.5px">{sub}</div><div style="margin-top:5px">{chip}</div></div></div>'
okc=lambda l='As planned':f'<span class="sch" style="background:var(--done-tint);color:var(--done)">{ic("check",13,2.4)}{l}</span>'
DIET=f'''<div class="row sp" style="margin-top:4px">{cav("Aarav")}<div class="f1" style="margin-left:12px"><div class="t-head">Aarav Sharma</div><div class="t-sub">Saturday, 14 Nov · plan 1,850 kcal</div></div></div>
<div class="card" style="padding:14px 16px;margin-top:14px"><div class="row" style="gap:14px"><div class="rc" style="position:relative">{ring(1292,1850,84,8)}<div class="in" style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center"><span class="n-md">1,292</span><span class="t-cap">kcal</span></div></div>
<div class="f1 col" style="gap:6px">{''.join(f'<div class="row sp"><span class="t-sub">{l}</span><span class="n-sm">{v}<span class="t-cap"> / {g} g</span></span></div>' for l,v,g in [("Protein",69,110),("Carbs",158,210),("Fat",36,55)])}</div></div></div>
<div class="t-label glabel">Meals · 4 of 5 logged</div><div class="group">{mrow("Early morning","6:30 am","Soaked almonds · 6",50,50,okc())}{mrow("Breakfast","8:52 am","Vegetable poha, masala chai, banana",412,412,okc())}
{mrow("Lunch","1:42 pm","2 roti, dal tadka, ½ katori rice (added), salad",610,560,'<span class="sch" style="background:var(--warn-tint);color:var(--warn)">'+ic("repeat",13,2.4)+'Changed portion</span>')}
{mrow("Evening snack","5:04 pm","Roasted chana, masala chai",220,220,okc())}{mrow("Dinner","8:30 pm","Paneer bhurji, 2 roti, raita",'—',560,'<span class="sch" style="background:var(--fill);color:var(--ink2)">'+ic("clock",13,2.4)+'Not due yet</span>')}</div>'''
screen('TM-12a-diet-day-review','Trainee diet day: planned vs actual per meal',page(nav("Food",right=f'<span class="navbtn">{ic("chevron-left",20,2.2)}</span><span class="navbtn">{ic("chevron-right",20,2.2)}</span>'),DIET),A)
P2=f'''<div class="row sp"><div><div class="t-title">Priya · Dinner</div><div class="t-sub">Fri 13 Nov · ate out</div></div><span class="sch" style="background:var(--warn-tint);color:var(--warn)">{ic("utensils-crossed",13,2.4)}Ate out</span></div>
<div class="row" style="gap:10px;margin-top:14px"><div class="f1 card" style="padding:12px;background:var(--bg);box-shadow:none"><div class="t-cap">Plan</div><div class="n-lg">560</div><div class="t-cap">Paneer bhurji, 2 roti</div></div><div class="f1 card" style="padding:12px;background:var(--warn-tint);box-shadow:none"><div class="t-cap">Logged</div><div class="n-lg" style="color:var(--warn)">1,120</div><div class="t-cap">kcal only</div></div></div>
<div class="card" style="padding:12px 14px;margin-top:10px;background:var(--bg);box-shadow:none"><div class="t-cap">Priya’s note</div><div class="t-body" style="font-size:15px">Office party · biryani and gulab jamun</div></div>
<div class="row" style="gap:10px;margin-top:14px">{btn("Add note","secondary",icon="notebook-pen",style="flex:1")}{btn("WhatsApp","tint",icon="message-circle",style="flex:1")}</div>'''
screen('TM-12b-diet-meal-sheet-ate-out','Meal detail sheet: ate out vs plan',page(nav("Food"),DIET.replace("Aarav Sharma","Priya Nair").replace(cav("Aarav"),cav("Priya")))+sheet(P2),A)
screen('TM-03h-client-loading-error','Client page couldn’t load',page(nav("",left="back"),f'<div style="margin-top:150px">{empty("cloud-off","Couldn’t load Rohan’s page","Check your connection and pull down to try again.",btn("Try again","tint",icon="refresh-cw"))}</div>'),A)
